<?php
function page_catalog():void {
 $list=rows("SELECT p.*,c.name coop_name,r.name raw_name,s.legal_name FROM products p JOIN cooperatives c ON c.id=p.coop_id JOIN suppliers s ON s.id=c.supplier_id JOIN raw_types r ON r.id=p.raw_type_id WHERE p.is_active=1 AND p.stock>0 AND c.status='verified' AND s.status='verified' ORDER BY p.name");
 ?><div class="row g-3"><?php foreach($list as $p):?><div class="col-md-6 col-xl-4"><div class="panel panel-pad h-100 d-flex flex-column"><div class="d-flex justify-content-between align-items-center mb-3"><span class="chip"><?=e($p['raw_name'])?></span><span class="helper">SKU <?=e($p['sku'])?></span></div><div style="background:#eaf0e3;border-radius:12px;height:120px;display:grid;place-items:center;font-size:53px">🥥</div><h5 class="mt-3"><?=e($p['name'])?></h5><p class="helper"><?=e($p['coop_name'])?> · <?=e($p['legal_name'])?></p><div class="mt-auto"><div class="d-flex justify-content-between align-items-center mb-2"><strong style="font-size:20px"><?=money($p['price'])?></strong><span class="helper">per kg</span></div><div class="helper mb-3">Stok tersedia: <?=number($p['stock'])?> kg</div><form method="post"><?=csrf_input()?><input type="hidden" name="action" value="new_order"><input type="hidden" name="product_id" value="<?=$p['id']?>"><div class="mb-2"><?php field('Jumlah pesan (kg)','quantity','number','','required min="0.01" step="0.01" max="'.e($p['stock']).'"');?></div><div class="mb-2"><?php field('Kota tujuan','city');?></div><div class="mb-2"><label class="form-label">Alamat pengiriman</label><textarea class="form-control" name="shipping_address" required rows="2"></textarea></div><div class="mb-3"><?php field('Catatan','notes','text','','');?></div><button class="btn btn-coco w-100">Ajukan pesanan</button></form></div></div></div><?php endforeach;?></div><?php if(!$list):?><div class="panel"><?php table_empty('Belum tersedia produk yang memiliki stok.');?></div><?php endif;?>
<?php }
